#include <Arduino.h>

/* Hardware and system limits */
#define MAX_SENSORS 10                  /* Maximum number of configurable sensor slots */
#define MAX_USERS 5                     /* Maximum user accounts (Flash/RAM budget) */
#define MOVING_AVG_WINDOW 10            /* Samples in the trimmed-mean sliding window */
#define SIMUT_VERSION "v3.42.3" /* Fix duplo: (A) Boot recovery — factory boot travava no cal-touch-screen quando touch HW está stuck-true: o while-loop interno aguardava 4 taps válidos, mas com touched()=true permanente o loop ou era infinito ou produzia cal degenerada. AppManager_Boot agora aplica default cal segura (xMin=200, xMax=3900, yMin=200, yMax=3900, zTh=400) sempre que isTouchCalibrated()==false no boot, e segue. User recalibra via Settings → Touch Cal quando o HW estiver OK. Default ranges cobrem maioria dos painéis XPT2046 — touch funcional após cal proper. Sem este fix, qualquer LFS reformatada (factory, OTA stage abort, picotool erase) levava a brick até reflash limpo + tap correto na tela em HW de touch funcionando. (B) Fix Fase 5 OTA: handler /api/restore?op=stage faltava branch UPLOAD_FILE_END no upload callback — sem ele, stage_session_end (xor-out CRC + pad da última página) NUNCA era chamado, status ficava em STAGING ao chegar no finish handler, e finish dispara abort → cliente recebia 422 com st=6 (ABORTED), bytes=0, crc=0 mesmo após upload completo bem-sucedido. Adicionado branch UPLOAD_FILE_END que chama stage_session_end só pro path stage (restore não tem finalize separado). v3.42.1: Fix: touch stuck-true no boot disparava AP mode falso. XPT2046 estava reportando touched()=true permanente desde reset (controller em estado indeterminado pré-Z-axis sample), e a janela de detecção AP-hold de 3s aceitava esse stale como gesture válido — device caia em AP a cada boot. AppManager_Boot agora roda settle period (até 1500ms aguardando 200ms consecutivos de quiet) ANTES da janela; se nunca viu quiet (stuck), bypass total da janela AP detect (forceAP fica false). Logs Serial debug (`[BOOT] touch settle: quiet=N ms=M` e `[BOOT] AP detect: forceAP=N`) capturados via reload+monitor pra confirmar quiet=0 no HW atual. AP por touch fica indisponível enquanto stuck (workaround: `conf system touch reset` via CLI). v3.42.0: OTA Fase 5 fechada (código) — upload do firmware .bin.gz pra staging via POST /api/restore?op=stage. Reuso da rota /api/restore + dispatch por query param (consistente com op=validate|apply da Fase 2 — economiza +16 KiB de WebServer per-route). src/ota/firmware_stage.{h,cpp}: state machine StageSession (IDLE→STAGING→STAGED ou *_FAILED/ABORTED) com page-buffer de 256 B, CRC32 running e flush alinhado a OTA_FLASH_PAGE_SIZE; padding 0xFF no last page (write granularity da flash QSPI). Em UPLOAD_FILE_START o callback chama stage_session_begin (LFS unmount + erase 1 MB de staging em ~5-10s); em WRITE alimenta page-buf + flush; em ABORT/erro chama stage_session_abort (remount LFS — reformata transparente). No finish (op=stage), sucesso (STAGED) também remonta LFS (Fase 5 não persiste staging — Fases 6/7 vão manter LFS desmontada entre upload e validate/apply). Pré-check de PERM_FILE_UPLOAD em UPLOAD_FILE_START antes de erase pra evitar destruição não autorizada; finish responde 200/422 com {st,bytes,crc32}. Flash: 1.024.312→1.025.160 B (+848 B / 0.83 KiB) — bem abaixo dos ~3 KiB estimados; margem livre 19.7→18.87 KiB. v3.41.1: OTA prep Fase 5: cortou 6.4 KiB de flash substituindo 2 sscanf("%4d-%2d-%2d") em cmdHandleSetTime por strtol manual — sscanf puxava __ssvfscanf_r + __ssvfiscanf_r (12 KB combined) do newlib só pra parsing trivial de data/hora CLI. Margem livre 13.4→19.7 KiB. -specs=nano.specs e -Wl,-u,_printf_float adicionados ao build_flags como guarda explícita (arduino-pico já usa nano por default; redundância intencional pra blindar contra mudança futura do core). v3.41.0: OTA Fase 4 fechada (código) — src/ota/ota_layout.h com layout REAL do flash investigado via builder PlatformIO (sketch=1020KB em vez de 1024 do plano §3; staging=1024KB; metadata=4KB era EEPROM emulada — SIMUT não usa EEPROM, "roubada"). src/ota/staging.{h,cpp} expõe staging_erase_all/erase_sector/write/read + staging_session_begin/end + staging_selftest, todas com __not_in_flash_func e save_and_disable_interrupts. Reusa StorageManager::enterFlashSafeMode (Core 1 lockout existente). Validação in-situ POSTERGADA pra Fase 5: adicionar endpoint web GET solo pra selftest puxava ~3KB de flash_range_* do Pico SDK estourando margem; vale pagar esse custo só quando upload real consumir staging. Staging code é GC'd em produção atual (1.030.776 B = +8B vs Fase 3, 13.4 KiB margem livre preservada). v3.40.0: OTA Fase 3 fechada — gunzip decompressor (uzlib 2.9.5 vendored em lib/uzlib/). Wrapper src/ota/decompressor.{h,cpp} expõe API ONE-SHOT PULL-BASED (gunzip_decompress com source_callback). Divergência do plano §6: uzlib NÃO suporta streaming push verdadeiro — uma vez source esgota mid-decode, estado corrompe (verificado empiricamente). Caller fornece src_cb que devolve byte sob demanda; em produção: Fase 5 acumula upload em LittleFS antes de chamar; Fase 7 lê staging via XIP. Tests host-side em test/test_decompressor (env:native_decompressor): 6/6 passam — small_blob, large_blob_500k (sha256 idêntico), pull_byte_by_byte (200 linhas variadas), bitflip_detected (3 posições), callback_abort, truncated_input. RAM: GunzipContext ~33KB BSS (32KB dict + state) — 1 instance por vida. Flash: ZERO em produção atual (uzlib + wrapper GC'd até Fase 5 ter consumidor real). Smoke test in-situ pulado: snprintf machinery somaria ~16KB; validação real virá quando apply chamar gunzip pela primeira vez. v3.39.0: OTA Fase 2 fechada — validação + restore de .bkp via state machine streaming. POST /api/restore?op=validate|apply (ROTA ÚNICA com query param — 2 rotas POST com upload callback custariam +16KB no WebServer arduino-pico). Modo VALIDATE: lê e CRC-verifica sem tocar LittleFS; APPLY: escreve direto nos paths finais (sem .tmp+rename — economiza 15KB de LittleFS.rename) com pool in-memory de paths para rollback em failure. UI: botão "Restore" no /files com fluxo validate→confirm→apply. backup_status_str removido (cliente mapeia códigos numéricos do enum). 13/13 casos HW passaram (st=0 backup íntegro, st=6 chip mismatch, st=1 bad magic, st=5 payload CRC corrompido, apply restaura 31 arquivos com SHA256 idêntico em 29 não-log). Flash: 1.028.648→1.030.768 B (+2.120 B / 2,1 KiB). RAM: +2.180 B (pool 2KB+offsets). Caveats: failure no apply deleta parcialmente escritos (originais já sobrescritos — não é "atomic" estrito do plano §6); migração de schema é placeholder vazio (schema 1 único existente). v3.38.0: OTA Fase 1 fechada — backup .bkp da LittleFS atrelado ao chip_id (RP2040 unique ID). Novo módulo src/ota/ (backup_format.h + backup.cpp com CRC32 EDB88320 incremental + tabela 1KB, walk DFS profundidade 8, dois passes scan/emit sem buffer total em RAM). Endpoint GET /api/backup gera arquivo BKP1 (header 40B + payload TLV) com Content-Length exato e Content-Disposition backup_<chip_id>_<ts>.bkp. UI: botão "Backup" no /files. Validador standalone tools/verify_backup.py (Python 3 stdlib only) verifica magic, header CRC, payload CRC, walk TLV. 18/18 casos de teste HW passaram (auth pre/pós-login, integridade, regressão endpoints, cross-check chip_id e6642815e34c1824). Flash: 1.026.704→1.028.648 B (+1.944 B / 1,9 KiB). v3.37.8: re-introduzido CMD_DBG_SENSOR_HISTORY_ALL (removido em v3.24.15 / EXT-002) — comando oculto pra recuperar visualização de histórico pré factory reset zerando provisionEpoch dos sensores. Sintaxe: 'conf sensor <N> history all' ou 'conf sensor all history all'. Restrito a sessão Bluetooth autenticada (BT só valida slot 0 = admin); USB serial responde com "comando desconhecido". CommandManager ganhou wasLastInputFromBt() flag setada por processInput. Após o comando, usar 'write memory' + 'reload' pra aplicar. Não listado em help. v3.37.7: dots licença removidos + auth keypad fix. */ /* Fase 18 fechada (Profissionalização — auditoria pós-v3.35.0). Cinco sub-fases entregues e validadas em HW: 18.1 hardening web (XSS escape + rate-limit calib + mask t_key, v3.36.0); 18.2 parsing robustness (parseIntStrict + path normalize O(n) + safety counters, v3.36.1); 18.3 refactor + qualidade (executeCommand 952L→624L + zero warnings + Reserved.h map + broken-pipe observability, v3.36.2); 18.4 observabilidade (audit log tags + parseFloatStrict tests + doc OTA + schema invariant, v3.36.3); 18.5 polish (M3 mutex timeout API + M5 drift detection doc + G3 CSS comment cleanup, v3.37.0). M4 (TODOs sem rastreio) auditado: zero TODO/HACK/FIXME no código próprio. G1/G2/G4 deliberadamente skip (cosmético puro, sem ganho funcional). Total: 76/76 testes HW passam acumulado (29 + 12 + 9 + 10 + 12 + 4 host). Flash 98.2%, heap 58KB. */

#define GRAPH_WIDTH 200                 /* Maximum data points on the TFT graph */

/**
 * @brief Índices nomeados para o array de cache min/max (sensores + board temp).
 *
 * Os slots 0–9 correspondem aos sensores configuráveis (MAX_SENSORS).
 * O slot 10 é reservado para a temperatura interna da placa (board temp).
 * MINMAX_SLOT_COUNT define o tamanho total dos arrays de cache.
 */
enum MinMaxSlot {
    MINMAX_SLOT_BOARD_TEMP = MAX_SENSORS,   /**< Índice da board temp no cache   */
    MINMAX_SLOT_COUNT      = MAX_SENSORS + 1 /**< Tamanho total do array de cache */
};

/* Permission bitmasks for role-based access control (RBAC) */
#define PERM_DASHBOARD   0x0001
#define PERM_HISTORY     0x0002
#define PERM_LOGS        0x0004
#define PERM_SYS_CONFIG  0x0008
#define PERM_NET_CONFIG  0x0010
#define PERM_FILE_READ   0x0020
#define PERM_FILE_UPLOAD 0x0040
#define PERM_FILE_DELETE 0x0080
#define PERM_USER_MGR    0x0100
#define PERM_CALIB       0x0200   /* v3.34.0: calibração de sensores via /dashboard */

#define PERM_FULL_ADMIN  0xFFFF
